@preconcurrency import SwiftNumber
@preconcurrency import Eth
import Foundation

public enum CCTPv2Actions {
    public static let creationCode: Hex = ""
    public static let runtimeCode: Hex = ""

    public static let MintingFailedError = ABI.Function(
            name: "MintingFailed",
            inputs: []
    )


    public enum RevertReason : Equatable, Error {
        case mintingFailed
        case unknownRevert(String, String)
    }
    public static func rewrapError(_ error: ABI.Function, value: ABI.Value) -> RevertReason {
        switch (error, value) {
        case (MintingFailedError, _):
            return .mintingFailed
        case let (e, v):
            return .unknownRevert(e.name, String(describing: v))
        }
    }
    public static let errors: [ABI.Function] = [MintingFailedError]
    public static let functions: [ABI.Function] = [bridgeUSDCFn, mintUSDCFn]
    public static let bridgeUSDCFn = ABI.Function(
            name: "bridgeUSDC",
            inputs: [.address, .uint256, .uint32, .bytes32, .address, .uint256, .uint32, .bool],
            outputs: []
    )

    public static func bridgeUSDC(tokenMessenger: EthAddress, amount: Number, destinationDomain: UInt, mintRecipient: Hex, burnToken: EthAddress, maxFee: Number, minFinalityThreshold: UInt, cappedMax: Bool, withFunctions ffis: EVM.FFIMap = [:]) throws -> Result<(), RevertReason> {
            do {
                let query = try bridgeUSDCFn.encoded(with: [.address(tokenMessenger), .uint256(amount), .uint32(destinationDomain), .bytes32(mintRecipient), .address(burnToken), .uint256(maxFee), .uint32(minFinalityThreshold), .bool(cappedMax)])
                let result = try EVM.runQuery(bytecode: runtimeCode, query: query, withErrors: errors, withFunctions: ffis)
                let decoded = try bridgeUSDCFn.decode(output: result)

                switch decoded {
                case  .tuple0:
                    return .success(())
                default:
                    throw ABI.DecodeError.mismatchedType(decoded.schema, bridgeUSDCFn.outputTuple)
                }
            } catch let EVM.QueryError.error(e, v) {
                return .failure(rewrapError(e, value: v))
            }
    }


    public static func bridgeUSDCDecode(input: Hex) throws -> (EthAddress, Number, UInt, Hex, EthAddress, Number, UInt, Bool) {
        let decodedInput = try bridgeUSDCFn.decodeInput(input: input)
        switch decodedInput {
        case let .tuple8(.address(tokenMessenger), .uint256(amount), .uint32(destinationDomain), .bytes32(mintRecipient), .address(burnToken), .uint256(maxFee), .uint32(minFinalityThreshold), .bool(cappedMax)):
            return  (tokenMessenger, amount, destinationDomain, mintRecipient, burnToken, maxFee, minFinalityThreshold, cappedMax)
        default:
            throw ABI.DecodeError.mismatchedType(decodedInput.schema, bridgeUSDCFn.inputTuple)
        }
    }

    public static let mintUSDCFn = ABI.Function(
            name: "mintUSDC",
            inputs: [.address, .address, .address, .uint256, .uint256, .uint256, .uint256],
            outputs: []
    )

    public static func mintUSDC(tStoracle: EthAddress, messageTransmitter: EthAddress, recipient: EthAddress, sourceChainId: Number, destinationChainId: Number, inputAmount: Number, maxFee: Number, withFunctions ffis: EVM.FFIMap = [:]) throws -> Result<(), RevertReason> {
            do {
                let query = try mintUSDCFn.encoded(with: [.address(tStoracle), .address(messageTransmitter), .address(recipient), .uint256(sourceChainId), .uint256(destinationChainId), .uint256(inputAmount), .uint256(maxFee)])
                let result = try EVM.runQuery(bytecode: runtimeCode, query: query, withErrors: errors, withFunctions: ffis)
                let decoded = try mintUSDCFn.decode(output: result)

                switch decoded {
                case  .tuple0:
                    return .success(())
                default:
                    throw ABI.DecodeError.mismatchedType(decoded.schema, mintUSDCFn.outputTuple)
                }
            } catch let EVM.QueryError.error(e, v) {
                return .failure(rewrapError(e, value: v))
            }
    }


    public static func mintUSDCDecode(input: Hex) throws -> (EthAddress, EthAddress, EthAddress, Number, Number, Number, Number) {
        let decodedInput = try mintUSDCFn.decodeInput(input: input)
        switch decodedInput {
        case let .tuple7(.address(tStoracle), .address(messageTransmitter), .address(recipient), .uint256(sourceChainId), .uint256(destinationChainId), .uint256(inputAmount), .uint256(maxFee)):
            return  (tStoracle, messageTransmitter, recipient, sourceChainId, destinationChainId, inputAmount, maxFee)
        default:
            throw ABI.DecodeError.mismatchedType(decodedInput.schema, mintUSDCFn.inputTuple)
        }
    }

}